package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;
@Entity @Table(name="accounts_payable")public class CuentaPagar{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false)private UUID empresaId;@Column(name="purchase_invoice_id",nullable=false,updatable=false)private UUID facturaId;@Column(name="supplier_id",nullable=false)private UUID proveedorId;@Column(name="currency_id",nullable=false)private UUID monedaId;@Column(name="due_date",nullable=false)private LocalDate vencimiento;@Column(name="original_amount",nullable=false,precision=19,scale=4)private BigDecimal montoOriginal;@Column(name="applied_amount",nullable=false,precision=19,scale=4)private BigDecimal montoAplicado;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private EstadoCuentaPagar status;@Column(nullable=false)private boolean voided;@Column(name="created_at",nullable=false,insertable=false,updatable=false)private OffsetDateTime creadaEn;@Column(name="created_by",nullable=false)private UUID creadaPor;protected CuentaPagar(){}public CuentaPagar(UUID t,UUID e,UUID f,UUID p,UUID m,LocalDate v,BigDecimal total,UUID u){tenantId=t;empresaId=e;facturaId=f;proveedorId=p;monedaId=m;vencimiento=v;montoOriginal=total;montoAplicado=BigDecimal.ZERO;status=total.signum()==0?EstadoCuentaPagar.PAID:EstadoCuentaPagar.PENDING;creadaPor=u;}public void anular(){voided=true;}public BigDecimal saldo(){return montoOriginal.subtract(montoAplicado);}public BigDecimal getMontoOriginal(){return montoOriginal;}public BigDecimal getMontoAplicado(){return montoAplicado;}public EstadoCuentaPagar getEstado(){return status;}public LocalDate getVencimiento(){return vencimiento;}public boolean isAnulada(){return voided;}}
